"""Prepare explicit new disclosure adapters for the remaining digital conference."""
import json
from datetime import datetime,timezone
from apply_di7_ap_as_01 import G,R,A,info,encoded

def main():
 out=R/'data/director/spell_review/de4_visibility_adapter_options_06.json';report=A/'DE4_VISIBILITY_OPTIONS_CHECK_06.json'
 assert not out.exists() and not report.exists()
 candidate=R/'data/director/spell_proposals/divination_enchantment_rank4_current_05.json';catp=R/'data/public/spell_playtests/catalog.json';cat=json.loads(catp.read_bytes())
 for i,sid in [(220,'mark-omen'),(222,'fate-coin'),(402,'arcane-ray'),(426,'burning-hands')]:assert cat['spells'][i]['id']==sid
 policy={
 'id':'DE4-VISIBILITY-06-PROPOSED','status':'NEW proposal for explicit Director disposition; not a claimed existing grant or application of the unfinished review',
 'common':'A disclosure adapter belongs to the original source/event and applies identically whether or not anyone owns a Fate permission. Resolve it after the complete original RNG operation, before eligible rerolls and consequences. It changes no dice, timing, number of draws, resource cost, target set or seed. It provides an authorized event handle and the exact original component IDs/faces only to its named audience. Server-only seed/state, undisclosed targets, modifiers and source causes remain private. Authorized replacement results use the same audience and component scope; they create no second original disclosure event. A player controlling several bodies does not grant each body another body’s perception, range, hand or Reaction. No disclosure adapter overrides an actual source protection.',
 'ownDeclaredAttack':{
  'sourceScope':'An actual player-controlled character’s deliberately declared ordinary weapon, natural, unarmed or spell attack against a creature/object it actually perceives, under the original attack source. Includes actual Arcane Ray catalog /spells/402. Excludes another body’s attack, autonomous companion attacks, unknown-location/blind-fire attempts, secret attacks, nonattack checks/saves and automatic results. A distinct source-specific policy would be required for those.',
  'audience':'Only the controller of the actual attacking character; not allies, enemies or an observing Coin holder merely because they see the attacker.',
  'generator':'The actual attacking body, retaining the original source’s special origin where expressly applicable; this adapter grants no new spatial origin.',
  'disclosure':'Complete original attack d20 component faces and IDs, die size, and effective higher/lower/ordinary selection mode. Show the full actual one- or two-d20 procedure; never a favorable subset. Do not reveal target AC, hidden flat modifiers, undisclosed sources or their identities, hit/miss or damage consequences before their normal checkpoint.',
  'explicitInformationChoice':'This intentionally makes the effective d20 procedure of the actor’s own declared perceived-target attack visible even when an underlying cause of advantage/disadvantage remains undisclosed. Effective selection mode is a newly permitted narrow gameplay fact; cause/identity remains private. This is a consequential NEW choice for GPT to approve or replace, not an inference from camera visibility. It must be rejected/restricted explicitly if the game requires effective advantage state itself to remain secret.',
  'noAdditionalAccess':'Having this readout supplies no reroll by itself. All actual Mark Omen, Fate Coin or Fate Reversal permission/cost/guard/Reaction/source predicates still apply.'},
 'ownBurningHands':{
  'sourceScope':'Only actual Burning Hands /spells/426 with its original 15ft cone, DEX-save factor and one shared 3d6 pool; no extension to other fire spells, other damage pools, loot or generation RNG.',
  'audience':'Only the actual original caster’s controller.',
  'generator':'Actual original caster body, not an arbitrary recipient or UI animation.',
  'disclosure':'The complete shared three d6 component IDs and faces, with their ordinary summed raw pool, after the real pool is generated and before any recipient damage consequences. Every actual recipient still uses that same final shared pool with its own save/defenses.',
  'eventExistence':'Do not add a roll when the original source does not generate one. This grant requires at least one actual eligible cone recipient already independently perceived/known to this caster at resolution; otherwise this adapter grants no event handle or component readout. The response must not disclose whether additional hidden recipients exist, their number, identities, saves, defenses, eligibility or outcomes. One known recipient is sufficient irrespective of hidden-recipient count.',
  'otherObservers':'An outside holder H has no grant from this adapter; N02’s old observer-positive branch stays conditional. A new own-caster fixture is provided instead.'},
 'affectedConfusionController':{
  'sourceScope':'Only the operative proposed Confusion behavior d4, nonempty target-selection 1dN and direction d8 at that affected body’s actually authorized opportunity; both printed school modes keep their actual access.',
  'audience':'Only the controller retaining decisions for the affected creature T. Confusion’s caster and outside Coin holders gain nothing merely by perceiving T.',
  'generator':'The affected T body at its actual behavior opportunity. No caster-location substitution.',
  'disclosure':'Expose the completed d4 face before executing its branch. For a branch that actually calls for a later d8 or nonempty 1dN, expose that completed result before its movement/target consequence. Each is a distinct original event. For 1dN, show only the already-perceived legal candidate bodies and stable component-to-candidate mapping; never include unperceived U. Empty set creates neither draw nor reroll offer. Direction shows only the source’s fixed eight-direction mapping, no route/hidden-hazard data.',
  'reaction':'Confusion itself retains target-controlled Bonus Actions/Reactions and creates no general Reaction prohibition. T can use its own existing Coin with usable hand and actual available Reaction if all source predicates pass; prior spending, actual Incapacitated or another prohibition still blocks use. No extra refresh, compelled Coin spending or new physical item is supplied.',
  'guard':'Using Coin on d4 consumes its actual item/Reaction and that event’s guard; it does not automatically fund or grant another use on the separate later dN/d8 event. The normal actual resource limits still apply.'},
 'remainingClosed':'No other source obtains a digital disclosure grant here. Positive outside-observer/save/check cases remain explicitly conditional composition tests until their own original source policy is authored. Negative hidden/total-only tests remain valid. These narrow adapters do not claim exhaustive presentation coverage of every eligible Fate source.'}
 vectors=[{'id':'DE4-V06-A','source':'Actual Arcane Ray /spells/402; actual Mark Omen /spells/220; pending Fate Reversal','scope':'Named-source caster sequence plus declared target/interface values, not a complete game runtime','setup':{'actor':'Wizard7, INT18, PB3, prepared three named spells, Abjuration specialization','RP':{'initial':24,'MarkOmenPaidAt0':2,'ReversalPaidAt6':7,'ArcaneRayPaidAt12':0,'remaining':15},'Dissonance':'First distinct prepared names; base0 and no Refrain extra','Mark':'target T remains legally marked at t12; its source deadline not reset','Reversal':'operative self permission from t6, expiry66, Reaction available','advantage':'Actual ally Help Action at t11 against T within5ft; physical assistance legal, Wizard is first helped attacker before Help expiry','T':'Actual perceived enemy creature, unarmored AC12 from DEX14, within Arcane Ray30ft and LoE, no other defense','allFaces':'ownDeclaredAttack adapter; only Wizard controller'},'operation':{'originalAttackFaces':[4,17],'originalModifier':7,'firstLegalCommitment':'Wizard voluntarily chooses Mark Omen','replacementFaces':[1,4],'attemptedLaterReversal':'same original lineage'},'expected':{'finalSelectedFace':4,'finalTotal':11,'hit':False,'MarkSpent':True,'ReversalSpent':False,'ReactionSpent':False,'replacementDraws':2,'damageDraws':0,'originalAttackCount':1,'otherObserversGrantedFaces':False}},
 {'id':'DE4-V06-B','source':'Actual Burning Hands /spells/426 and Fate Coin /spells/222','scope':'Named-source sequence; original two known eligible recipient failed saves are declared fixed resolution inputs','setup':{'caster':'Wizard1 INT18 PB2; actually prepared both spells; legal V/S/F','RP':{'initial':4,'CoinPriorPaid':2,'BurningHandsPaid':2,'remaining':0},'Coin':'same conjured unspent physical coin in usable hand, within original3600s, Reaction available','knownConeRecipients':2,'originalFailedDexSaves':True,'bothUnresistant':True,'casterOutsideSeal':'if one recipient is protected, original Evocation/caster generator stays unprotected under pending Seal rule','visibility':'ownBurningHands only; no outside holder granted faces'},'operation':{'pool':[2,4,6],'selectedComponent':'first d6','replacement':5},'expected':{'pool':[5,4,6],'sharedRawTotal':15,'eachFailedSaveRecipientPacket':15,'CoinSpent':True,'ReactionSpent':True,'damageLineageGuardSpent':True,'replacementDraws':1,'hiddenRecipientInformationDisclosed':False},'negativeBranch':'Without a known eligible original recipient this adapter grants no event handle or faces, regardless of whether the engine privately generates a pool. Coin remains unspent, no diagnostic reason is sent, and no extra draw occurs.'},
 {'id':'DE4-V06-C','source':'Proposed Confusion /spells/9/procedure and actual Coin /spells/222','scope':'Composition fixture after a lawfully established Confusion and existing paid Coin; no setup cast/cost is fabricated','setup':{'T':'affected creature with normal Action, usable hand, operative Coin and actual Reaction after required regular START processing','d4Original':3,'d4CoinUse':False,'candidateSnapshot':['A_friend','B_enemy','C_enemy'],'unperceivedUExcluded':True,'outsideObserverH':'perceives T at20ft but has no source disclosure grant'},'operation':{'targetDrawD3':2,'T_CoinReplacement':1},'expected':{'target':'A_friend','ordinaryAttacks':1,'ordinaryActionSpent':True,'T_CoinSpent':True,'T_ReactionSpent':True,'H_CoinSpent':False,'H_PromptOffered':False,'candidateSetRebuilt':False,'newHardGuardClaim':False},'negativeBranches':['If T already spent its Reaction or is actually prohibited, no Coin use commits; original index2 selects B.','Empty candidate set creates no target draw, no target reroll prompt, and no alternate behavior.','Selecting A grants only the actual ordinary legal attack and required ordinary ammunition, never optional class/RP expenditure.']}]
 sources=[candidate,catp,R/'data/public/class_playtests/wizard.json',R/'docs/mechanics/COMBAT_ACTION_PLAYTEST.md',R/'docs/mechanics/CORE_RESOLUTION_PLAYTEST.md',R/'docs/mechanics/VIDEO_GAME_ONLY_DIRECTIVE.md']
 checks=[('source identities actual',True),('Wizard7 RP cost sequence',24-2-7==15),('Wizard1 cost sequence',4-2-2==0),('whole advantage replacement',max([1,4])+7==11),('miss AC12',11<12),('shared pool replacement',5+4+6==15),('finite target selection',[ 'A_friend','B_enemy','C_enemy'][1-1]=='A_friend'),('three source scoped adapters',all(k in policy for k in ['ownDeclaredAttack','ownBurningHands','affectedConfusionController']))]
 assert all(v for _,v in checks)
 out.write_bytes(encoded({'id':'DE4-VISIBILITY-ADAPTER-OPTIONS-06','createdAtUtc':datetime.now(timezone.utc).isoformat(),'status':'Unsent pending discussion; based on observed review issue, no completed-review receipt or acceptance claimed','proposal':policy,'vectors':vectors,'questionForDirector':'Please explicitly agree or give exact minimal corrections, especially the newly permitted effective own-attack d20 mode and the affected-controller versus observer distinction. Does this bounded first coverage sufficiently resolve the DE4 source-readout decision while conditional tests remain labeled and all undefined sources fail closed?','sourceBindings':[info(p) for p in sources],'newRuleAdoptions':0,'originalSourceEdits':0,'runtimeTestsExecuted':0}))
 report.write_bytes(encoded({'artifact':info(out),'checks':[{'check':n,'passed':v} for n,v in checks],'checkCount':len(checks),'failureCount':0,'scope':'Source identities, direct resource/arithmetic/finite-selection checks only; visibility choices require semantic review.'}))
 print(json.dumps({'artifact':info(out),'checks':len(checks),'failures':0}))

if __name__=='__main__':main()
